WITH RECURSIVE x6 AS (SELECT 1 INTERSECT SELECT x5.v1896 + 1 FROM x13) SELECT x5.v1896, x5.v1897, ST_ASTEXT(ST_CONVEXHULL(ST_GEOMFROMTEXT('LINESTRING(0 0, 5 5)'))) AS x3, x5.v1898 FROM v1894 AS x5 WHERE EXISTS(SELECT x5.v1896, x5.v1896, SUM(x5.v1898) FROM x9 AS x14 WHERE x5.v1897 = x5.v1898 GROUP BY x5.v1895, x5.v1895 WITH ROLLUP HAVING SUM(x5.v1898) > 40 ORDER BY x5.v1895, x5.v1898)